{
  "summary": "As a married first‑timer couple without children or an expected baby, you do not meet the criteria for the FT(PMC) or FCS priority schemes, so no priority scheme applies to improve your BTO ballot chances.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "The FT(PMC) priority scheme is for first‑timer families that have at least one Singapore Citizen child aged 18 or below, or are expecting a child, and the couple must be aged 40 or below.",
      "cited_fact_ids": ["PRI-FTPMC-001"]
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "The FCS (Proximity) priority scheme gives priority to parents and their children (including engaged couples) who apply to live together or close by.",
      "cited_fact_ids": ["PRI-FCS-001"]
    },
    {
      "claim_id": "c3",
      "kind": "caveat",
      "text": "Because you have no child and are not expecting, you do not satisfy the eligibility conditions of either FT(PMC) or FCS, so no priority scheme applies to your BTO ballot.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Prepare identity documents, employment and income records for both applicants, and any supporting paperwork for self‑employment and CPF contributions. Also gather relationship proof if required for an engaged couple.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "preparation_step",
      "text": "Obtain a valid Singapore NRIC for each applicant.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c2",
      "kind": "preparation_step",
      "text": "For Jia Hui (Employed with CPF contributions), collect recent payslips, CPF contribution statements, and the latest Notice of Assessment (NOA) from IRAS.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "For Ken (Self‑Employed), gather the latest Income Tax Notice of Assessment, audited or unaudited financial statements, and any business registration documents (e.g., ACRA BizFile).",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "If either applicant has more than one job, ensure that employment documents are provided for each job (as per DOC-JOBS-001).",
      "cited_fact_ids": ["DOC-JOBS-001"]
    },
    {
      "claim_id": "c5",
      "kind": "preparation_step",
      "text": "Prepare a declaration of household composition, including any other occupiers (e.g., parents or children) and their NRICs.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c6",
      "kind": "preparation_step",
      "text": "If HDB requires proof of relationship for an engaged couple, be ready to submit a statutory declaration or other acceptable evidence of engagement.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c7",
      "kind": "caveat",
      "text": "The exact list of required documents may vary; confirm the latest checklist on the HDB website or the HDB Flat Portal before submission.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [
    {
      "field": "relationship",
      "needed_for": ["hfe_process"],
      "follow_up_question": "Will you be married before submitting the HFE application, or will you remain engaged at that time?"
    }
  ],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "If you receive a queue number and choose not to book a flat, you will receive a non‑selection count which may affect your future first‑timer priority and could move you to the second‑timer category for a year.",
  "claims": [
    {
      "claim_id": "c1",
      "text": "An applicant who is invited to book a flat but does not book is treated as rejecting the chance and receives a non‑selection count.",
      "kind": "policy_fact",
      "cited_fact_ids": ["NS-COUNT-001"]
    },
    {
      "claim_id": "c2",
      "text": "A non‑selection count moves the applicant’s later flat applications into the second‑timer category for one year and resets any extra ballot chances built up from earlier unsuccessful first‑timer applications.",
      "kind": "policy_fact",
      "cited_fact_ids": ["NS-FT-001"]
    },
    {
      "claim_id": "c3",
      "text": "If you receive a second non‑selection count within that year, your first‑timer priority is suspended for an additional year.",
      "kind": "policy_fact",
      "cited_fact_ids": ["NS-FT-001"]
    },
    {
      "claim_id": "c4",
      "text": "You may still apply for future BTO or SBF exercises, but your eligibility for first‑timer priority will be affected as described above.",
      "kind": "preparation_step",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Since the application period has already closed, you can still request cancellation via MyRequest@HDB, but it will be processed only after the ballot results are released and the application will still be entered into the ballot.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "A flat application cancelled within the sales exercise's application period carries no penalty and can be cancelled any time before the period closes.",
      "cited_fact_ids": ["NS-CANCEL-001"]
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "After the application period ends, cancellation must be requested through MyRequest@HDB and cannot be processed before ballot results are released; the application will still go into the ballot.",
      "cited_fact_ids": ["NS-CANCEL-002"]
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Submit a cancellation request via MyRequest@HDB and wait for HDB to process it after the ballot results are announced.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c4",
      "kind": "caveat",
      "text": "The policy does not specify a monetary penalty for cancelling after the application period, but you should confirm any possible fees or implications on the HFE letter with HDB directly.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "As a Singapore Citizen with a non‑resident spouse, you can apply for a 2‑room Flexi flat. You need to obtain a valid Singpass, ensure the Work Pass is valid, apply for an HFE letter and gather the required documents before the flat application.",
  "claims": [
    {
      "claim_id": "c1",
      "text": "A Singapore Citizen whose spouse is a non‑resident can only buy a 2‑room Flexi flat when buying a new flat from HDB.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HH-NONRES-001"]
    },
    {
      "claim_id": "c2",
      "text": "The non‑resident spouse must hold a valid Work Pass when the HFE letter is applied for and again when the flat application is made.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HH-NONRES-003"]
    },
    {
      "claim_id": "c3",
      "text": "For a new flat bought with a non‑resident spouse, the Singapore Citizen applicant must be at least 35 years old.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HH-NONRES-002"]
    },
    {
      "claim_id": "c4",
      "text": "Every applicant and every required occupier needs a valid Singpass account at the time of the HFE letter application.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HFE-SINGPASS-001"]
    },
    {
      "claim_id": "c5",
      "text": "An HFE letter stays valid for 9 months from the date HDB issues it.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HFE-VALID-001"]
    },
    {
      "claim_id": "c6",
      "text": "If the HFE letter will expire within 30 days and you still need time to submit a flat application, you should apply for a fresh letter.",
      "kind": "policy_fact",
      "cited_fact_ids": ["HFE-RENEW-001"]
    },
    {
      "claim_id": "c7",
      "text": "Prepare a valid Singpass for both you (the applicant) and your spouse (as a required occupier).",
      "kind": "preparation_step",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c8",
      "text": "Ensure your spouse's Work Pass is valid throughout the HFE application and flat purchase process; renew it if it is due to expire.",
      "kind": "preparation_step",
      "cited_fact_ids": ["HH-NONRES-003"]
    },
    {
      "claim_id": "c9",
      "text": "Gather the documents needed for the HFE letter: identification (NRIC for you, passport and Work Pass for your spouse), proof of employment, and any other documents HDB requests.",
      "kind": "preparation_step",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c10",
      "text": "Apply for the HFE letter via the HDB Flat Portal using your Singpass; the letter will be valid for 9 months.",
      "kind": "preparation_step",
      "cited_fact_ids": ["HFE-VALID-001"]
    },
    {
      "claim_id": "c11",
      "text": "After receiving the HFE letter, monitor its expiry date and re‑apply for a fresh letter if needed before the flat application deadline.",
      "kind": "preparation_step",
      "cited_fact_ids": ["HFE-RENEW-001"]
    },
    {
      "claim_id": "c12",
      "text": "When the BTO ballot opens, use the HFE letter to apply for a 2‑room Flexi flat; ensure you meet any additional documentation requirements at that stage.",
      "kind": "preparation_step",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Your HFE letter remains valid for a flat application as long as it was still valid when you submitted the application; however, we need to know its issue date to confirm if it will still be valid for the upcoming launch.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "If a flat application was submitted while the HFE letter was valid, the purchase can go ahead even after the letter expires, and no new HFE letter is needed for that application.",
      "cited_fact_ids": ["HFE-VALID-002"]
    },
    {
      "claim_id": "c2",
      "kind": "caveat",
      "text": "The exact validity period of an HFE letter (e.g., six months from issue) is not specified in the provided policy facts, so you should check the expiry date shown on your HFE letter or on the HDB portal.",
      "cited_fact_ids": []
    }
  ],
  "missing_profile_fields": [
    {
      "field": "hfe_issue_date",
      "needed_for": ["validity_assessment"],
      "follow_up_question": "When was your HFE letter issued (date shown on the letter)?"
    }
  ],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}

{
  "summary": "Both Joanne and Wesley should gather their recent payslips, CPF contribution records and any bonus details, and indicate ‘Employed with CPF contributions’ as their employment status in the HFE income section.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "The HFE application requires each applicant to select an employment status from six options, including ‘Employed with CPF contributions’ for salaried employees who receive CPF contributions from both employee and employer.",
      "cited_fact_ids": ["DOC-STATUS-001"]
    },
    {
      "claim_id": "c2",
      "kind": "preparation_step",
      "text": "Joanne and Wesley should each select ‘Employed with CPF contributions’ as their employment status in the HFE application.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c3",
      "kind": "policy_fact",
      "text": "If an applicant has more than one job, they must enter the number of positions and provide employment status and income for each job.",
      "cited_fact_ids": ["DOC-MULTIJOB-001"]
    },
    {
      "claim_id": "c4",
      "kind": "caveat",
      "text": "Both applicants have only one job, so they will enter ‘1’ for the number of positions and provide details for that single job.",
      "cited_fact_ids": []
    },
    {
      "claim_id": "c5",
      "kind": "preparation_step",
      "text": "Gather recent payslips covering the assessment period to verify monthly salary figures.",
      "cited_fact_ids": ["DOC-MULTIJOB-003"]
    },
    {
      "claim_id": "c6",
      "kind": "preparation_step",
      "text": "Obtain CPF contribution history (e.g., CPF statement) for the assessment period to confirm contributions from both employee and employer.",
      "cited_fact_ids": ["DOC-MULTIJOB-003"]
    },
    {
      "claim_id": "c7",
      "kind": "preparation_step",
      "text": "If any bonuses were received during the assessment period, note the amount and the month received, and be ready to enter it separately in the ‘Received Bonus’ field.",
      "cited_fact_ids": ["DOC-MULTIJOB-003"]
    },
    {
      "claim_id": "c8",
      "kind": "policy_fact",
      "text": "When asked for employment or trade documents, applicants must provide them for every job they hold.",
      "cited_fact_ids": ["DOC-JOBS-001"]
    },
    {
      "claim_id": "c9",
      "kind": "preparation_step",
      "text": "Prepare digital copies of payslips, CPF statements, and any bonus letters to upload when prompted for employment documents.",
      "cited_fact_ids": ["DOC-JOBS-001"]
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}
